"""Portable shared concept stylesheet; tokens are a verbatim source snapshot."""
TOKENS = '/* Initial concept palettes. Spacing: 4, 8, 12, 16, 24, 32, 48. */\n:root {\n  --simple-bg: #EFFAFC;\n  --simple-surface: #FFFFFF;\n  --simple-text: #123743;\n  --simple-muted: #4D707B;\n  --simple-primary: #087F91;\n  --simple-accent: #16B3C7;\n  --simple-peach: #FFF0E7;\n  --simple-yellow: #FFE195;\n  --natural-bg: #F7F8F2;\n  --natural-surface: #FFFFFF;\n  --natural-text: #203C31;\n  --natural-muted: #58665C;\n  --natural-accent: #326347;\n  --warm-bg: #FFF7EF;\n  --warm-surface: #FFFFFF;\n  --warm-text: #452D29;\n  --warm-muted: #795C51;\n  --warm-accent: #A5412C;\n  --dark-bg: #141C1B;\n  --dark-surface: #202C29;\n  --dark-text: #F1F4EA;\n  --dark-muted: #B3C0B6;\n  --dark-accent: #D2ED9B;\n  --space-sm: 8px;\n  --space-md: 16px;\n  --space-lg: 24px;\n  --space-xl: 32px;\n  --radius-card: 24px;\n}\n'
CSS = '\n/* Type and controls follow implementation-guide: body 16, heading 24/28,\n   48px controls; sizes reuse the established spacing scale. */\n*{box-sizing:border-box}body{margin:0;padding:var(--space-xl);background:var(--simple-bg);color:var(--simple-text);font:16px/1.5 Arial,sans-serif}h1{font-size:28px;line-height:1.2;margin:0 0 var(--space-sm);font-weight:800}h2{font-size:24px;line-height:1.25;margin:0 0 var(--space-lg);font-weight:800}h3{font-size:16px;line-height:1.4;margin:0 0 var(--space-sm)}p{margin:0;color:var(--simple-muted)}a{color:var(--simple-primary)}.subtitle{margin-bottom:var(--space-lg)}.screens{display:flex;gap:var(--space-lg);align-items:stretch}.panel{width:400px;flex-shrink:0;display:flex;flex-direction:column}.phone{display:flex;flex:1;flex-direction:column;min-height:1104px;background:var(--simple-bg);border:2px solid var(--simple-text);border-radius:var(--space-xl);overflow:hidden}.status{padding:var(--space-md) var(--space-lg) 0;font-weight:bold}.status span{float:right}header{display:flex;align-items:center;gap:var(--space-md);padding:var(--space-md) var(--space-lg)}.back{display:flex;align-items:center;justify-content:center;background:var(--simple-surface);color:var(--simple-text);border-radius:var(--space-md);width:48px;height:48px;font-size:32px}.brand{font-size:24px;font-weight:800;display:flex;align-items:center;gap:var(--space-sm)}.brand img{width:32px;height:32px;object-fit:contain}.progress{display:flex;align-items:center;gap:var(--space-sm);padding:0 var(--space-lg) var(--space-md)}.progress i{height:8px;flex:1;background:var(--simple-surface);border:1px solid var(--simple-muted);border-radius:var(--space-sm)}.progress i.filled{background:var(--simple-primary);border-color:var(--simple-primary)}.progress b{margin-left:var(--space-sm)}main{padding:var(--space-md) var(--space-lg);flex:1}main>p{margin:var(--space-md) 0}.art{width:80px;height:80px;object-fit:contain;float:right;margin:0 0 var(--space-md) var(--space-md)}.hero{clear:both;text-align:center;margin:0 0 var(--space-lg)}.hero img{width:calc(var(--space-xl)*5);height:calc(var(--space-xl)*4);object-fit:contain}.hero p{font-size:16px}.card{clear:both;border-radius:var(--radius-card);padding:var(--space-md);background:var(--simple-surface);margin:0 0 var(--space-md)}.card:last-child{margin-bottom:0}.notice,.error{background:var(--simple-peach)}.notice p,.error{color:var(--simple-text)}.selected{outline:2px solid var(--simple-primary);outline-offset:-2px}.row{display:flex;align-items:center;gap:var(--space-md);min-height:80px}.row>div{min-width:0;flex:1}.row-art{width:64px;height:64px;flex-shrink:0;object-fit:contain}.row h3{margin-bottom:4px}.goal-grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-md);clear:both}.goal-grid .row{display:flex;flex-direction:column;text-align:center;margin:0;align-items:center}.goal-grid .row div{width:100%}.goal-grid .row-art{width:80px;height:80px}.goal-grid p{display:none}.options{display:flex;flex-wrap:wrap;gap:var(--space-sm);margin:var(--space-sm) 0}.option{background:var(--simple-bg);padding:var(--space-sm);border-radius:var(--space-sm);min-height:48px;display:flex;align-items:center;color:var(--simple-text);flex-grow:1;justify-content:center}.option.selected{color:var(--simple-primary);font-weight:bold;background:var(--simple-surface)}label{display:block;font-weight:bold;clear:both;margin:0 0 var(--space-md)}.field{display:flex;justify-content:space-between;align-items:center;gap:var(--space-sm);font-weight:normal;border:1px solid var(--simple-muted);border-radius:var(--space-md);padding:var(--space-md);background:var(--simple-surface);min-height:56px;margin-top:var(--space-sm)}.inline-error{clear:both;background:var(--simple-peach);color:var(--simple-text);padding:var(--space-sm) var(--space-md);border-radius:var(--space-sm);margin:calc(-1 * var(--space-sm)) 0 var(--space-md)}.stepper{display:flex;align-items:center;justify-content:space-between;gap:var(--space-sm)}.stepper span{display:flex;min-width:48px;min-height:48px;align-items:center;justify-content:center;background:var(--simple-bg);color:var(--simple-primary);border-radius:var(--space-sm);font-size:24px}.stepper b{min-width:48px;text-align:center}.check,.confirm{clear:both}.chip{display:table;clear:both;background:var(--simple-surface);color:var(--simple-primary);padding:var(--space-sm) var(--space-md);border-radius:var(--space-md);font-weight:bold;margin-bottom:var(--space-md)}footer{padding:var(--space-sm) var(--space-lg) 0}.button{border-radius:var(--space-md);background:var(--simple-primary);color:var(--simple-surface);font-weight:bold;min-height:56px;padding:var(--space-md);text-align:center}.button.disabled{background:var(--simple-surface);border:1px solid var(--simple-muted);color:var(--simple-muted)}.secondary{color:var(--simple-primary);min-height:56px;padding:var(--space-md) 0;text-align:center;font-weight:bold}nav{display:flex;gap:4px;padding:var(--space-sm);background:var(--simple-surface)}nav div{flex:1;font-size:11px;color:var(--simple-muted);text-align:center;padding:var(--space-sm) 0;min-height:64px}nav b{display:block;font-size:24px;line-height:1.2;color:inherit}nav .active{color:var(--simple-primary);font-weight:bold;background:var(--simple-bg);border-radius:var(--space-md)}.handle{height:4px;width:96px;background:var(--simple-text);border-radius:4px;margin:var(--space-sm) auto}.panel-caption{margin-top:var(--space-md);font-weight:bold;color:var(--simple-text)}.caption{margin-top:var(--space-lg);max-width:1040px}.week{display:flex;gap:4px;margin:var(--space-md) 0}.day{background:var(--simple-surface);border-radius:var(--space-md);min-width:0;flex:1;text-align:center;padding:var(--space-sm) 0;font-size:12px}.day b{display:block;font-size:16px}.day.selected{color:var(--simple-primary);font-weight:bold}.camera-frame{border:2px dashed var(--simple-primary);border-radius:var(--radius-card);padding:var(--space-lg);margin-top:var(--space-md)}.loader{width:48px;height:48px;border:8px solid var(--simple-bg);border-top-color:var(--simple-primary);border-radius:50%;margin:var(--space-lg) auto}.measure{margin-bottom:var(--space-md)}.measure-row{display:flex;align-items:center;justify-content:space-between;gap:var(--space-sm);padding:var(--space-sm);background:var(--simple-surface);border-radius:var(--space-sm)}.sex{margin-top:var(--space-lg)}small{font-size:16px;color:var(--simple-muted)}.choices{background:var(--simple-surface);padding:var(--space-md);border-radius:var(--space-md)}.index-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:var(--space-lg);margin:var(--space-lg) 0}.index-card{background:var(--simple-surface);border-radius:var(--radius-card);padding:var(--space-lg)}.index-card img{width:100%;height:180px;object-fit:contain;object-position:left top}.index-card a{display:inline-flex;min-height:48px;align-items:center;margin-right:var(--space-md)}\n\n.allergen-grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-sm);clear:both;margin-bottom:var(--space-md)}.allergen-grid .row{flex-direction:column;text-align:center;margin:0;padding:var(--space-sm);gap:var(--space-sm)}.allergen-grid .row-art{width:48px;height:48px}.health-list{clear:both;background:var(--simple-surface);border-radius:var(--radius-card);padding:var(--space-md);margin-bottom:var(--space-md)}.health-row{display:flex;align-items:center;justify-content:space-between;gap:var(--space-sm);min-height:64px;padding:var(--space-sm) 0;border-bottom:1px solid var(--simple-bg)}.health-row b{flex:1}.health-row span{flex-shrink:0;min-height:48px;display:flex;align-items:center}.measure-row .stepper b{font-size:16px;min-width:64px}\n\n.ingredient .stepper{justify-content:flex-start}.ingredient .text-action{color:var(--simple-primary);font-weight:bold;min-height:48px;display:flex;align-items:center;justify-content:flex-end}.ingredient{padding-bottom:var(--space-sm)}\n\n.measure{clear:both}.measure-row{flex-wrap:wrap}.measure-row .stepper{flex-shrink:0}.measure-row .stepper b{max-width:160px;overflow-wrap:anywhere}.error{padding:var(--space-md);border-radius:var(--space-md);margin-bottom:var(--space-md)}\n'

# Small link and active navigation text must pass 4.5 on the pale background.
CSS += "\na{color:var(--simple-text)}.secondary{color:var(--simple-text)}nav .active{color:var(--simple-text)}\n"
